package protocol

// Catálogo Oficial de Protocolos y Opcodes de Fiesta Online (XelionCore).
// Extraído directamente desde los flujos TPI/PDB oficiales (Zone.pdb, WorldManager.pdb, Account.pdb, etc.).
//
// Fórmula bitfield oficial NETCOMMAND de 16 bits:
//   protocol = (department << 10) | command
//
// Cero Omisiones, Cero Resúmenes, 100% Fidelidad Binaria.

// MakeOpCode packs a department (0..63) and a command (0..1023) into a uint16 opcode.
func MakeOpCode(dept uint8, cmd uint16) uint16 {
	return (uint16(dept) << 10) | (cmd & 0x3FF)
}

// ExtractHeader returns the department (category) from an opcode.
func ExtractHeader(opcode uint16) uint8 {
	return uint8(opcode >> 10)
}

// ExtractType returns the command ID from an opcode.
func ExtractType(opcode uint16) uint16 {
	return opcode & 0x3FF
}

